    import sys

    input = sys.stdin.read().split()
    idx = 0
    G = int(input[idx])
    N = int(input[idx + 1])
    M = int(input[idx + 2])
    idx += 3

    mutations = {}
    for _ in range(N):
        a = int(input[idx])
        k = int(input[idx + 1])
        mutation = tuple(int(input[i]) for i in range(idx + 2, idx + 2 + k))
        if a not in mutations:
            mutations[a] = []
        mutations[a].append(mutation)
        idx += 2 + k

    antibodies = []
    for _ in range(M):
        l = int(input[idx])
        antibody = tuple(int(input[i]) for i in range(idx + 1, idx + 1 + l))
        antibodies.append(antibody)
        idx += 1 + l

    def contains_antibody(virus):
        for antibody in antibodies:
            if antibody in virus:
                return True
        return False

    def bfs(start):
        queue = deque([(start,)])
        visited = set([start])
        while queue:
            current_virus = queue.popleft()
            if contains_antibody(current_virus):
                continue
            for gene in current_virus:
                if gene >= 2:
                    for mutation in mutations[gene]:
                        new_virus = current_virus[:current_virus.index(gene)] + mutation + current_virus[current_virus.index(gene) + 1:]
                        if new_virus not in visited:
                            visited.add(new_virus)
                            queue.append(new_virus)
        return visited

    results = []
    for gene in range(2, G):
        if gene not in mutations:
            results.append("YES")
            continue
        all_viruses = bfs((gene,))
        detectable = all(contains_antibody(virus) for virus in all_viruses)
        if detectable:
            results.append("YES")
        else:
            min_length = min(len(virus) for virus in all_viruses if not contains_antibody(virus))
            results.append(f"NO {min_length}")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
